async () => {
  const log = await connecta.call("ci.get_run_log", { runId: 4812 });

  // Parse the log to find failures
  const lines = log.split('\n');
  const failures = {};

  for (const line of lines) {
    // Look for FAIL entries
    if (line.includes('FAIL')) {
      const match = line.match(/\[shard \d+\/\d+\] FAIL (.+\.test\.ts)/);
      if (match) {
        const testFile = match[1];
        failures[testFile] = (failures[testFile] || 0) + 1;
      }
    }
  }

  // Look for final status or summary that shows which test failed the run
  let runFailedTest = null;
  for (const line of lines) {
    if (line.includes('run 4812 failed') || line.includes('Failed tests') || line.includes('FAILED')) {
      console.log("Status line:", line);
      // Extract test name from summary
      const match = line.match(/(.+\.test\.ts)/);
      if (match) {
        runFailedTest = match[1];
      }
    }
  }

  console.log("Failures found:", failures);
  console.log("Run failed test:", runFailedTest);

  // Return the test file that caused the run to fail
  if (runFailedTest) {
    return runFailedTest;
  } else if (Object.keys(failures).length === 1) {
    return Object.keys(failures)[0];
  } else if (Object.keys(failures).length > 1) {
    // Multiple failures - find the one that appears only once (not retried)
    for (const [test, count] of Object.entries(failures)) {
      if (count === 1) {
        return test;
      }
    }
  }

  return null;
}

async () => {
  const log = await connecta.call("ci.get_run_log", { runId: 4812 });

  // Parse all FAIL and PASS entries to track retries
  const lines = log.split('\n');
  const testStatus = {};

  for (const line of lines) {
    const failMatch = line.match(/\[shard \d+\/\d+\] FAIL (.+\.test\.ts)/);
    const passMatch = line.match(/\[shard \d+\/\d+\] PASS (.+\.test\.ts)/);

    if (failMatch) {
      const testFile = failMatch[1];
      if (!testStatus[testFile]) {
        testStatus[testFile] = [];
      }
      testStatus[testFile].push('FAIL');
    }
    if (passMatch) {
      const testFile = passMatch[1];
      if (!testStatus[testFile]) {
        testStatus[testFile] = [];
      }
      testStatus[testFile].push('PASS');
    }
  }

  // Find tests that failed and never passed (or failed last)
  let failedTests = [];
  for (const [test, statuses] of Object.entries(testStatus)) {
    const lastStatus = statuses[statuses.length - 1];
    if (lastStatus === 'FAIL') {
      failedTests.push({
        test: test,
        statuses: statuses
      });
    }
  }

  console.log("Test status details:");
  failedTests.forEach(t => {
    console.log(`${t.test}: ${t.statuses.join(' -> ')}`);
  });

  // Return the test that failed the run
  if (failedTests.length === 1) {
    return failedTests[0].test;
  } else if (failedTests.length > 1) {
    // Return the first one that appears to be the actual failure
    return failedTests[0].test;
  }

  return null;
}

